import{_ as t,c as e,a2 as s,o as r}from"./chunks/framework.DPuwY6B9.js";const i="/assets/sit.DujHrjbm.webp",l="/assets/car3.Cp-gHO_8.webp",o="/assets/xcd.BfhitSGN.webp",c="/assets/ygd.CEyTGYCZ.webp",h="/assets/ygddy.C4z83SBF.webp",p="/assets/zxd.BzyA4U3W.webp",n="/assets/ssd.L6VV0fOJ.webp",d="/assets/wd.D9G_xdzH.webp",m="/assets/car4.DYWy5nUF.webp",b="/assets/qbmq.DrhMr8iD.webp",u="/assets/hbmq.AFV762hu.webp",q="/assets/hsjmq.FZRSJjGp.webp",_="/assets/car1.DaoBxTtN.webp",f="/assets/car2.DUbps6xk.webp",k="/assets/xwg.BODH1Bf6.webp",x="/assets/mlyz.DnrUKAFV.webp",S=JSON.parse('{"title":"用车技巧","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"life/car.md","filePath":"life/car.md","lastUpdated":1727530975000}'),P={name:"life/car.md"};function g(w,a,v,D,B,y){return r(),e("div",null,a[0]||(a[0]=[s('<h1 id="用车技巧" tabindex="-1">用车技巧 <a class="header-anchor" href="#用车技巧" aria-label="Permalink to &quot;用车技巧&quot;">​</a></h1><h2 id="开车" tabindex="-1">开车 <a class="header-anchor" href="#开车" aria-label="Permalink to &quot;开车&quot;">​</a></h2><h3 id="驾驶坐姿" tabindex="-1">驾驶坐姿 <a class="header-anchor" href="#驾驶坐姿" aria-label="Permalink to &quot;驾驶坐姿&quot;">​</a></h3><p>右脚直踩刹车，斜踩加速。（电车无离合器）</p><p><img src="'+i+'" alt="驾驶坐姿"></p><h3 id="后视镜调节" tabindex="-1">后视镜调节 <a class="header-anchor" href="#后视镜调节" aria-label="Permalink to &quot;后视镜调节&quot;">​</a></h3><p><img src="'+l+'" alt="后视镜调节"></p><h3 id="灯光使用" tabindex="-1">灯光使用 <a class="header-anchor" href="#灯光使用" aria-label="Permalink to &quot;灯光使用&quot;">​</a></h3><h4 id="行车灯" tabindex="-1">行车灯 <a class="header-anchor" href="#行车灯" aria-label="Permalink to &quot;行车灯&quot;">​</a></h4><p><img src="'+o+'" alt="行车灯"> 行车灯也叫做示宽灯，它的作用是使车辆的四个角为人所见，亮度没有大灯那么高。在雨天、天色昏暗或者在地下停车场时应亮起此灯。行车灯亮起时，仪表盘上会亮起如图所示的标志。</p><h4 id="远光灯" tabindex="-1">远光灯 <a class="header-anchor" href="#远光灯" aria-label="Permalink to &quot;远光灯&quot;">​</a></h4><p><img src="'+c+'" alt="远光灯"></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><ol><li><p>大灯闪一下：提示前方车辆让出车道或同意对方并线 有时候前车由于一时走神或者对路况不熟，车速缓慢，挡住后车继续前进的路。此时后车司机可以把大灯闪一下，提示前车司机让道。</p></li><li><p>大灯闪两下：会车时，提醒对方把远光灯切换为近光灯 会车时，当对头车使用远光灯，严重影响你的视野，你可以闪两下大灯提醒来车要把大灯切换为近光灯。</p></li><li><p>大灯闪三下：提示前方司机其车辆出现了故障，应停车检查 如果发现前车的车门没有关好、尾灯烧了、轮胎没气等情况，可以对前车连闪大灯三下，提醒前车停车检查车辆。</p></li><li><p>连闪大灯：拒绝旁边车辆的并道要求或提醒行人或非机动车他们所处的是机动车道。</p></li></ol><p>当然，现在很多人开车不规矩，会胡乱闪灯，只能靠经验辨别。</p></div><p><img src="'+h+'" alt="远光灯灯语"></p><h4 id="转向灯" tabindex="-1">转向灯 <a class="header-anchor" href="#转向灯" aria-label="Permalink to &quot;转向灯&quot;">​</a></h4><p><img src="'+p+'" alt="转向灯"></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><ol><li>当大车一直打左转向灯却又迟迟未变道或减速，这是提醒你对面有来车或者前方有危险，可不要随意超车。</li><li>当大车在右车道打右转向灯，示意可以安稳的超车。</li></ol></div><h4 id="双闪灯" tabindex="-1">双闪灯 <a class="header-anchor" href="#双闪灯" aria-label="Permalink to &quot;双闪灯&quot;">​</a></h4><p><img src="'+n+'" alt="双闪灯"></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><ol><li>当大车双闪灯光同时结合远近光灯闪烁‌：表示前方可能有重大事故或其他极度危险情况，请立即减速并打开自己的双闪灯‌。</li><li>当后方车辆跟车太近‌：可以间断式的轻踩刹车亮刹车灯，开双闪灯‌。</li></ol></div><h4 id="雾灯" tabindex="-1">雾灯 <a class="header-anchor" href="#雾灯" aria-label="Permalink to &quot;雾灯&quot;">​</a></h4><p>有些车没有前雾灯，比如特斯拉。</p><p><img src="'+d+'" alt="雾灯"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>1.能见度小于500米大于200米时，必须开启近光灯、示宽灯和后雾灯；时速不得超过80km/h；保持150米以上的行车间距。<br> 2.能见度小于200米大于100米时，必须开启近光灯、示宽灯和前后雾灯；时速不得超过60km/h；保持100米以上的行车间距。<br> 3.能见度小于100米大于50米时，必须开启近光灯、示宽灯和前后雾灯；时速不得超过40km/h；保持50米以上的行车间距。<br> 4.能见度小于50米时，车辆禁止驶入高速公路。此时已进入高速公路的车辆，必须按规定开启有关灯光，驶离雾区，时速不得超过20公里。</p></div><h3 id="车距判断" tabindex="-1">车距判断 <a class="header-anchor" href="#车距判断" aria-label="Permalink to &quot;车距判断&quot;">​</a></h3><h3 id="应对爆胎" tabindex="-1">应对爆胎 <a class="header-anchor" href="#应对爆胎" aria-label="Permalink to &quot;应对爆胎&quot;">​</a></h3><p>当车辆突然爆胎的时候，第一时间要稳住方向盘并松开油门，千万不要急打方向或猛踩刹车。稳住车辆的方向后，缓慢减速，靠边停车，打开双闪。</p><h3 id="驾驶盲区" tabindex="-1">驾驶盲区 <a class="header-anchor" href="#驾驶盲区" aria-label="Permalink to &quot;驾驶盲区&quot;">​</a></h3><h4 id="概览" tabindex="-1">概览 <a class="header-anchor" href="#概览" aria-label="Permalink to &quot;概览&quot;">​</a></h4><p><img src="'+m+'" alt="驾驶盲区"></p><h4 id="车前盲区" tabindex="-1">车前盲区 <a class="header-anchor" href="#车前盲区" aria-label="Permalink to &quot;车前盲区&quot;">​</a></h4><p>以 SUV（长城赛弗）以及一台小型车（雪佛兰赛欧）为例。 <img src="'+b+'" alt="前部盲区"></p><h4 id="车后盲区" tabindex="-1">车后盲区 <a class="header-anchor" href="#车后盲区" aria-label="Permalink to &quot;车后盲区&quot;">​</a></h4><p><img src="'+u+'" alt="后部盲区"></p><h4 id="后视镜盲区" tabindex="-1">后视镜盲区 <a class="header-anchor" href="#后视镜盲区" aria-label="Permalink to &quot;后视镜盲区&quot;">​</a></h4><p><img src="'+q+'" alt="后视镜盲区"></p><h2 id="停车" tabindex="-1">停车 <a class="header-anchor" href="#停车" aria-label="Permalink to &quot;停车&quot;">​</a></h2><h4 id="倒车入库" tabindex="-1">倒车入库 <a class="header-anchor" href="#倒车入库" aria-label="Permalink to &quot;倒车入库&quot;">​</a></h4><h5 id="普通路" tabindex="-1">普通路 <a class="header-anchor" href="#普通路" aria-label="Permalink to &quot;普通路&quot;">​</a></h5><p><img src="'+_+'" alt="普通路如何倒车入库"></p><h5 id="窄路" tabindex="-1">窄路 <a class="header-anchor" href="#窄路" aria-label="Permalink to &quot;窄路&quot;">​</a></h5><ul><li>a. 贴库位线直至后轮与障碍物齐平 将自己的车贴着库位线，向超出库位的方向开，直到车后轮与库位边上的障碍物齐平，如果是库位边上的障碍物是车，也可以让自己与对方车的另一侧大灯齐平。</li><li>b. 向库位反方向打满轮，前进直至车位与障碍物边缘齐平 大概开出 60 CM 左右，让自己车与库位线不那么平行，方便入库。</li><li>c. 向库位方向打满轮，倒车入库 此时要注意车头不要撞到别的障碍物，车进库后可微调。</li></ul><h3 id="侧方位停车" tabindex="-1">侧方位停车 <a class="header-anchor" href="#侧方位停车" aria-label="Permalink to &quot;侧方位停车&quot;">​</a></h3><p><img src="'+f+'" alt="侧方停车四步法"></p><h3 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h3><p><img src="'+k+'" alt="限位杆"> 不要让轮胎一直压着限位桩，要保持一些距离，这样才能保护好轮胎。</p><p><img src="'+x+'" alt="马路牙子"> 在上马路牙子的时候要选好方向，轮胎正面接触马路牙子的伤害要比侧面小一些，接下来最关键的就是控制车速，待轮胎顶到马路牙子后再缓慢加油，切记不要图快“冲”上去。</p>',47)]))}const U=t(P,[["render",g]]);export{S as __pageData,U as default};
